INSERT INTO `shows` VALUES (1,'Tangled','tangled','A spirited princess with magical hair escapes her hidden tower and discovers the floating lights with an unlikely guide.','Animation, Family, Fantasy, Musical',100,'PG','/assets/movies/tangled/poster.webp','/assets/movies/tangled/backdrop.webp',0,'2026-08-29 14:49:34','archived','2026-09-05','2026-12-31','2026-08-05','enchanted_castle',NULL),(2,'Lilo & Stitch','lilo-and-stitch','A lonely Hawaiian girl adopts a mischievous alien and teaches him that family means nobody gets left behind.','Animation, Family, Science Fiction',92,'PG','/assets/movies/lilo-and-stitch/poster.webp','/assets/movies/lilo-and-stitch/backdrop.webp',0,'2026-08-29 14:49:46','archived','2026-09-05','2026-12-31','2026-08-05','ocean_and_islands',NULL),(3,'WALL-E','wall-e','A curious cleanup robot follows a sleek visitor into space and helps humanity rediscover its forgotten home.','Animation, Family, Science Fiction',98,'G','/assets/movies/wall-e/poster.webp','/assets/movies/wall-e/backdrop.webp',0,'2026-08-29 14:49:46','archived','2026-09-05','2026-12-31','2026-08-05','tech_and_arcade',NULL),(4,'The Avengers','the-avengers','Earth’s mightiest heroes must learn to work as one team when an unexpected enemy threatens global security.','Action, Adventure, Superhero',143,'PG-13','/assets/movies/the-avengers/poster.webp','/assets/movies/the-avengers/backdrop.webp',0,'2026-08-29 14:49:47','archived','2026-09-05','2026-12-31','2026-08-05','hero_city',NULL),(5,'Big Hero 6','big-hero-6','A young robotics prodigy joins his inflatable healthcare companion and a gifted group of friends to protect their city.','Animation, Family, Science Fiction',102,'PG','/assets/movies/big-hero-6/poster.webp','/assets/movies/big-hero-6/backdrop.webp',0,'2026-08-29 14:49:47','archived','2026-09-05','2026-12-31','2026-08-05','hero_city',NULL),(6,'Frozen','frozen','A fearless princess crosses a frozen kingdom to find her sister and restore summer with courage, friendship, and lo